// Clean Home: clock + quick buttons + a glass dock of your installed apps.
// apps.js is generated by `tv_customize.py home` from the TV's app list.
(function () {
  var cfg = window.HOME_CONFIG || { apps: [], theme: {} };
  var t = cfg.theme || {};
  var css = document.documentElement.style;
  if (t.background) css.setProperty("--bg", t.background);
  css.setProperty("--glow", t.background_glow || "transparent");
  if (t.text_color) css.setProperty("--text", t.text_color);
  if (t.accent) css.setProperty("--accent", t.accent);

  // ---- launching apps -------------------------------------------------
  function launch(id, params, fallback) {
    if (typeof PalmServiceBridge === "undefined") { console.log("launch", id, params); return; }
    var bridge = new PalmServiceBridge();
    bridge.onservicecallback = function (msg) {
      try {
        if (fallback && JSON.parse(msg).returnValue === false) launch(fallback.id, fallback.params);
      } catch (e) {}
    };
    var payload = { id: id };
    if (params) payload.params = params;
    bridge.call("luna://com.webos.applicationManager/launch", JSON.stringify(payload));
  }
  var ACTIONS = {
    inputs: function () { launch("com.webos.app.inputpicker", null, { id: "com.palm.app.settings" }); },
    wifi: function () { launch("com.palm.app.settings", { target: "network" }); },
    settings: function () { launch("com.palm.app.settings"); }
  };

  // ---- app grid (4 x 4, scrolls by row) -----------------------------
  var COLS = 4, ROWS = 4;
  var custom = t.colors || {};

  // Card colour: your override, else the icon's own colour (read when the
  // app was built), else read it from the icon here, else dark glass.
  function sampleIcon(img) {
    try {
      var c = document.createElement("canvas");
      c.width = c.height = 16;
      var ctx = c.getContext("2d");
      ctx.drawImage(img, 0, 0, 16, 16);
      var d = ctx.getImageData(0, 0, 16, 16).data, r = 0, g = 0, b = 0, n = 0;
      for (var i = 0; i < 16; i++) {
        [[i, 0], [i, 15], [0, i], [15, i]].forEach(function (p) {
          var k = (p[1] * 16 + p[0]) * 4;
          if (d[k + 3] > 128) { r += d[k]; g += d[k + 1]; b += d[k + 2]; n++; }
        });
      }
      return n > 32 ? "rgb(" + (r / n | 0) + "," + (g / n | 0) + "," + (b / n | 0) + ")" : "";
    } catch (e) { return ""; }   // icon not readable (different origin)
  }

  var track = document.getElementById("track");
  var cards = cfg.apps.map(function (app, i) {
    var card = document.createElement("div");
    card.className = "card";
    var over = custom[app.id] || custom[app.title];
    if (over) {
      var parts = String(over).split(",");
      card.style.background = parts.length > 1
        ? "linear-gradient(135deg," + parts[0] + "," + parts[1] + ")" : parts[0];
    } else if (app.colour) {
      card.style.background = app.colour;
    }
    function label() {
      var s = document.createElement("span");
      s.textContent = app.title;
      card.appendChild(s);
    }
    if (app.icon) {
      var img = document.createElement("img");
      img.src = app.icon;
      img.alt = app.title;
      img.onload = function () {
        if (!over && !app.colour) {
          var c = sampleIcon(img);
          if (c) card.style.background = c;
        }
      };
      img.onerror = function () { img.remove(); label(); };
      card.appendChild(img);
    } else {
      label();
    }
    card.onclick = function () { launch(app.id); };
    card.onmouseenter = function () { setFocus("dock", i); };
    track.appendChild(card);
    return card;
  });

  // ---- focus & remote keys ---------------------------------------------
  var pills = [].slice.call(document.querySelectorAll(".pill"));
  pills.forEach(function (p, i) {
    p.onclick = function () { ACTIONS[p.dataset.action](); };
    p.onmouseenter = function () { setFocus("pills", i); };
  });
  var zone = cards.length ? "dock" : "pills", idx = { dock: 0, pills: 0 }, topRow = 0;

  function setFocus(z, i) {
    var list = z === "dock" ? cards : pills;
    if (!list.length) return;
    zone = z;
    idx[z] = Math.max(0, Math.min(list.length - 1, i));
    cards.concat(pills).forEach(function (el) { el.classList.remove("focus"); });
    list[idx[z]].classList.add("focus");
    if (z === "dock") {
      // keep the focused row on screen (scrolls one row at a time)
      var row = Math.floor(idx.dock / COLS), rows = Math.ceil(cards.length / COLS);
      topRow = Math.min(Math.max(topRow, row - ROWS + 1), row);
      topRow = Math.max(0, Math.min(topRow, rows - ROWS));
      var step = cards[0].offsetHeight + parseFloat(getComputedStyle(track).rowGap || 0);
      track.style.transform = "translateY(" + (-topRow * step) + "px)";
    }
  }

  document.addEventListener("keydown", function (e) {
    switch (e.keyCode) {
      case 37: setFocus(zone, idx[zone] - 1); break;   // left
      case 39: setFocus(zone, idx[zone] + 1); break;   // right
      case 38:                                         // up
        if (zone === "dock" && idx.dock >= COLS) setFocus("dock", idx.dock - COLS);
        else setFocus("pills", idx.pills);
        break;
      case 40:                                         // down
        if (zone === "pills") setFocus("dock", idx.dock);
        else if (idx.dock + COLS < cards.length) setFocus("dock", idx.dock + COLS);
        else if (Math.floor(idx.dock / COLS) < Math.floor((cards.length - 1) / COLS)) setFocus("dock", cards.length - 1);
        break;
      case 13:                                         // OK
        if (zone === "dock" && cfg.apps[idx.dock]) launch(cfg.apps[idx.dock].id);
        if (zone === "pills") pills[idx.pills].click();
        break;
      case 461: break;                                 // Back: stay here
      default: return;
    }
    e.preventDefault();
  });
  setFocus(zone, 0);

  // ---- clock ---------------------------------------------------------
  var DAYS = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];
  var MONTHS = ["January", "February", "March", "April", "May", "June", "July",
                "August", "September", "October", "November", "December"];
  function tick() {
    var d = new Date(), h = d.getHours(), m = ("0" + d.getMinutes()).slice(-2);
    var greet = h < 5 ? "Good night" : h < 12 ? "Good morning" : h < 17 ? "Good afternoon" : "Good evening";
    document.getElementById("greeting").textContent = t.show_greeting === false ? "" : greet;
    if (t.clock_24h) {
      document.getElementById("time").textContent = ("0" + h).slice(-2) + ":" + m;
      document.getElementById("ampm").textContent = "";
    } else {
      document.getElementById("time").textContent = ((h % 12) || 12) + ":" + m;
      document.getElementById("ampm").textContent = h < 12 ? "AM" : "PM";
    }
    document.getElementById("date").textContent =
      DAYS[d.getDay()] + " " + d.getDate() + " " + MONTHS[d.getMonth()];
  }
  tick(); setInterval(tick, 5000);
})();
